mapper.select:
SELECT COUNT(*)
  FROM TB_CO_MODEL
 WHERE VEND_CODE = #{vendCode}
   AND MCN_TYPE = #{mcnType}
   AND MODEL_CODE = #{modelCode}

mapper.update:
UPDATE TB_CO_MODEL
   SET MODEL_NM = #{modelNm},
       LSCHG_DTM = #{lschgDtm},
       LS_CMENO = #{lsCmeno}
 WHERE VEND_CODE = #{vendCode}
   AND MCN_TYPE = #{mcnType}
   AND MODEL_CODE = #{modelCode}

mapper.delete:
DELETE FROM TB_CO_MODEL
 WHERE VEND_CODE = #{vendCode}
   AND MCN_TYPE = #{mcnType}
   AND MODEL_CODE = #{modelCode}
